    ('c9814b15-fcf6-539d-b6a1-dd2bc88d01e9'::uuid, 'Quiz — Construire un programme d’entraînement', 'Sport', '2de', 'S’entraîner et planifier', '4cd94eb3-e32f-5ef2-af71-3e750ab15917'::uuid),
