    ('f39bde39-5aaf-56c6-a019-7e9806b10c3c'::uuid, 'Quiz — Le sport comme fait social', 'Sport', '2de', 'Sport, société et valeurs', '14f35f33-a403-578a-ab5d-1fa7a7d3624c'::uuid),
