  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('e5bb30a6-021e-5372-a7fa-e17433631a41'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Respecter quelqu’un, c’est…', 'mcq', '["Reconnaître qu’il a la même valeur que soi","Être d’accord avec lui","Devenir son ami","Ne jamais lui parler"]'::jsonb, 0, 'Le respect n’exige pas l’accord : on peut être en désaccord et rester respectueux.', 1),
    ('3ebeaa9e-9ac9-51c7-92ca-719e20a614b4'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Qu’est-ce qu’une discrimination ?', 'mcq', '["Traiter quelqu’un moins bien pour ce qu’il est","Une punition scolaire","Un désaccord d’opinion","Une règle du règlement intérieur"]'::jsonb, 0, 'Origine, religion, handicap, sexe, apparence : la loi interdit ces différences de traitement.', 2),
    ('3c0dc5ea-a995-5013-9b05-e8554f065c6f'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Ce qui caractérise le harcèlement, c’est la répétition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un propos isolé blesse ; c’est la répétition qui fait le harcèlement.', 3),
    ('f6f14f84-fa1e-5f64-a23f-0521cf5e9570'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Quel numéro appeler en cas de harcèlement scolaire ?', 'mcq', '["3018","15","112","3939"]'::jsonb, 0, 'Le 3018 est le numéro national, gratuit, confidentiel, contre les violences numériques et le harcèlement.', 4),
    ('20ffc667-7dee-5576-a371-b7e82722620e'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Le harcèlement est toujours un peu la faute de la victime.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais. La responsabilité est entièrement du côté de celui qui harcèle.', 5),
    ('20241e69-de9a-5483-859e-4720c46e5372'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Que peut faire un témoin de harcèlement ?', 'mcq', '["Soutenir la victime et prévenir un adulte","Rire pour ne pas être visé","Filmer la scène","Ne rien faire, ça ne le regarde pas"]'::jsonb, 0, 'Le témoin n’est jamais neutre : se taire, c’est laisser faire.', 6),
    ('1e6f35ad-5858-5032-b284-3e13bc55cf58'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'Le règlement intérieur du collège…', 'mcq', '["S’applique à tous les élèves et adultes","Ne concerne que les élèves punis","Est facultatif","Change chaque semaine"]'::jsonb, 0, 'C’est la règle commune de l’établissement, connue de tous.', 7),
    ('a8351965-f64d-50b6-81bf-e2b7764a4a50'::uuid, '72e5216c-043e-55d3-9d51-32d2a0a888ff'::uuid, 'On peut être en désaccord avec quelqu’un tout en le respectant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est exactement ce qui permet de discuter au lieu de se battre.', 8),
    ('65c4b281-b928-5230-a339-669b1fc9fa20'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Quelle est la devise de la République française ?', 'mcq', '["Liberté, Égalité, Fraternité","Union, Force, Travail","Honneur, Patrie, Valeur","Paix, Travail, Patrie"]'::jsonb, 0, 'Elle est inscrite sur les frontons des mairies et des écoles.', 1),
    ('a6134473-cf1a-5b81-92a7-1b305c8ec789'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Qui est Marianne ?', 'mcq', '["La représentation allégorique de la République","Une reine de France","La première présidente","L’auteure de la Marseillaise"]'::jsonb, 0, 'Son buste est présent dans toutes les mairies.', 2),
    ('7ee57d21-68a8-539f-b211-fc8741d99203'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'La Marseillaise est l’hymne national français.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Écrite par Rouget de Lisle en 1792, elle devient hymne national en 1795.', 3),
    ('9e2e01fc-5b4a-5c35-bbd4-db113b0695ae'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Que signifie « la République est laïque » ?', 'mcq', '["L’État ne favorise aucune religion","Les religions sont interdites","Seul le catholicisme est reconnu","Chacun doit avoir une religion"]'::jsonb, 0, 'La laïcité garantit la liberté de croire ou de ne pas croire.', 4),
    ('d82616d1-0c1d-526a-a379-b70160c8e90e'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Quelle est la date de la fête nationale ?', 'mcq', '["Le 14 juillet","Le 8 mai","Le 11 novembre","Le 1er mai"]'::jsonb, 0, 'Elle commémore la prise de la Bastille (1789) et la Fête de la Fédération (1790).', 5),
    ('b72333e6-188a-5cb5-90bc-e4d28d998797'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, '« Indivisible » signifie que la loi est la même partout en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’article 1 de la Constitution.', 6),
    ('a94e7750-28a2-57bb-ba2d-b8eed49ad11f'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Que veut dire l’égalité en République ?', 'mcq', '["Les mêmes droits pour tous","Tout le monde gagne pareil","Tout le monde pense pareil","Personne ne travaille"]'::jsonb, 0, 'L’égalité est celle des droits, pas celle des situations.', 7),
    ('a00c8711-1da5-5911-affd-3c30ac482ee7'::uuid, '30f1b781-181e-57a5-8250-e464ed673c7d'::uuid, 'Quelles sont les couleurs du drapeau français ?', 'mcq', '["Bleu, blanc, rouge","Bleu, blanc, vert","Rouge, blanc, noir","Bleu, jaune, rouge"]'::jsonb, 0, 'Le bleu et le rouge sont les couleurs de Paris, le blanc celle de la royauté.', 8),
    ('d6654981-d267-542f-afcf-3b6a9d13aa61'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Jusqu’à quel âge l’instruction est-elle obligatoire en France ?', 'mcq', '["16 ans","14 ans","18 ans","15 ans"]'::jsonb, 0, 'Elle est obligatoire de 3 à 16 ans, puis une formation est obligatoire jusqu’à 18 ans.', 1),
    ('2da64df3-5ad3-5010-9539-3abf3e3bc132'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Comment sont désignés les délégués de classe ?', 'mcq', '["Élus par les élèves à bulletin secret","Désignés par le professeur principal","Tirés au sort","Choisis par le principal"]'::jsonb, 0, 'C’est un vote, premier apprentissage de la démocratie.', 2),
    ('b0e554fe-82fe-54e0-afb5-aa9180490cb1'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'L’assiduité est un devoir de l’élève.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Venir en cours et être à l’heure fait partie des obligations.', 3),
    ('c60bd113-82c7-5e25-8d5f-995b8404db23'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Que fait le conseil de classe ?', 'mcq', '["Il examine la scolarité de chaque élève","Il vote le budget du collège","Il élit le principal","Il note les professeurs"]'::jsonb, 0, 'Il réunit professeurs, délégués élèves et parents.', 4),
    ('6c4dcf95-8053-5d78-b691-f526e0005879'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Le droit d’exprimer son opinion permet d’insulter un camarade.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La liberté d’expression s’arrête là où commencent l’injure et la diffamation.', 5),
    ('fe234a4b-5657-5e79-b5a0-88fbcf248f73'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'À quoi sert le CVC ?', 'mcq', '["À permettre aux élèves de proposer des projets","À sanctionner les élèves","À recruter les professeurs","À noter la cantine"]'::jsonb, 0, 'Le conseil de la vie collégienne est une instance de participation des élèves.', 6),
    ('a8683619-2b16-585a-b302-f836b6737c6e'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Le règlement intérieur est…', 'mcq', '["Un contrat commun à tout l’établissement","Une liste de punitions","Une loi votée au Parlement","Un document réservé aux professeurs"]'::jsonb, 0, 'Il est présenté et signé en début d’année.', 7),
    ('7a603a96-728d-5f0f-9ccc-a88fef5f26b3'::uuid, '3ff1ea0b-182b-5cb1-bf83-1b7a13499b3f'::uuid, 'Un droit va toujours de pair avec un devoir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le droit d’être respecté implique le devoir de respecter.', 8),
    ('6b4e09e5-3587-5b2d-96dc-f4eb8d9c4983'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'Quelle loi fonde la laïcité en France ?', 'mcq', '["La loi de 1905","La loi de 1789","La loi de 1958","La loi de 2004"]'::jsonb, 0, 'La loi du 9 décembre 1905 sépare les Églises et l’État.', 1),
    ('a1f24ba6-5d73-58a5-aa0b-f5a9d4f9c42e'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'La laïcité signifie que les religions sont interdites.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle garantit au contraire la liberté de croire ou de ne pas croire.', 2),
    ('0ee140f6-510e-5f7a-99d4-adcaf815e343'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'Selon l’article 4 de la DDHC, la liberté consiste à…', 'mcq', '["Faire tout ce qui ne nuit pas à autrui","Faire absolument tout","Obéir au chef de l’État","Suivre sa religion"]'::jsonb, 0, 'La limite de ma liberté, c’est la liberté de l’autre.', 3),
    ('47a27128-9568-5787-aa32-52f5fa81979e'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'La diffamation est-elle protégée par la liberté d’expression ?', 'mcq', '["Non, c’est un délit","Oui, toujours","Oui, sur internet","Oui, entre amis"]'::jsonb, 0, 'Injure, diffamation, incitation à la haine : ce sont des délits, pas des opinions.', 4),
    ('7dbfa54f-2bb7-5059-94c4-767c9d4df14f'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'L’État français salarie-t-il les ministres du culte ?', 'mcq', '["Non, il ne finance ni ne salarie aucun culte","Oui, tous","Oui, seulement les prêtres","Oui, en Corse"]'::jsonb, 0, 'C’est l’article 2 de la loi de 1905.', 5),
    ('e5b2b64a-959c-5226-bb4d-85e25fcd17a1'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'La loi de 2004 concerne…', 'mcq', '["Les signes religieux ostensibles à l’école publique","Le port du casque à vélo","Le vote des femmes","La durée du travail"]'::jsonb, 0, 'Elle s’applique aux écoles, collèges et lycées publics.', 6),
    ('6b53e1a4-7e31-5e4e-ad60-c42e84dda878'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'La liberté de conscience inclut le droit de ne croire en rien.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Croire, ne pas croire, changer de croyance : tout est protégé.', 7),
    ('4b7745b0-94b8-5c1f-a7df-72f05a51fc93'::uuid, '9742efb5-f4a8-5801-9176-12692c0b20aa'::uuid, 'Quel texte de 1789 énonce les libertés fondamentales ?', 'mcq', '["La Déclaration des droits de l’homme et du citoyen","La Constitution de la Ve République","Le Code civil","Le traité de Rome"]'::jsonb, 0, 'Elle a valeur constitutionnelle aujourd’hui encore.', 8),
    ('5f24c580-326a-56c8-aa54-711feafe0347'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Quelle juridiction juge les crimes ?', 'mcq', '["La cour d’assises","Le tribunal de police","Le tribunal correctionnel","Le conseil de prud’hommes"]'::jsonb, 0, 'Elle comprend un jury populaire tiré au sort.', 1),
    ('6aa11432-add2-5a27-ac6f-65fbad6712e8'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Un vol est un…', 'mcq', '["Délit","Crime","Contravention","Litige civil"]'::jsonb, 0, 'Les délits sont jugés au tribunal correctionnel.', 2),
    ('edc3d47e-5456-5d70-9feb-c705d5e7200e'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'La présomption d’innocence signifie qu’on est innocent tant qu’on n’a pas été jugé coupable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un principe fondamental de tout procès équitable.', 3),
    ('c26381eb-3fc3-5c11-85b7-a45bb818b36a'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'La justice civile sert à…', 'mcq', '["Régler les conflits entre particuliers","Punir les crimes","Voter les lois","Contrôler la police"]'::jsonb, 0, 'Divorce, loyers, contrats : elle tranche sans punir.', 4),
    ('cb7facd9-4953-5de6-bf54-afaa367df231'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'À partir de quel âge un mineur peut-il être pénalement responsable ?', 'mcq', '["13 ans","10 ans","16 ans","18 ans"]'::jsonb, 0, 'En dessous, seules des mesures éducatives sont possibles.', 5),
    ('f5c61343-607f-56d4-93b1-9363db88b4d5'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Faire appel, c’est demander que l’affaire soit rejugée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un droit : une autre juridiction réexamine l’affaire.', 6),
    ('8d585398-842c-5892-83f7-0173b58c3b59'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'La justice des mineurs privilégie…', 'mcq', '["L’éducation sur la punition","La prison systématique","L’amende","Le renvoi de l’école"]'::jsonb, 0, 'C’est le principe posé par l’ordonnance de 1945, repris par le code de la justice pénale des mineurs.', 7),
    ('2885f099-0212-5723-8da5-f6ed139d2389'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Un procès contradictoire, c’est un procès où…', 'mcq', '["Chaque partie peut répondre à l’autre","Le juge décide seul sans écouter","Il n’y a pas d’avocat","Le public est interdit"]'::jsonb, 0, 'Le contradictoire garantit l’équité du débat.', 8),
    ('3c5593dc-a433-570b-8514-a33ff11e6b9a'::uuid, '16e80840-6ab1-5742-a371-0b65386c63e2'::uuid, 'À quel âge se fait le recensement citoyen ?', 'mcq', '["16 ans","15 ans","18 ans","14 ans"]'::jsonb, 0, 'Il ouvre la voie à la Journée défense et citoyenneté.', 1),
    ('dfea15ca-6c19-5e42-af89-8e206f09ae3a'::uuid, '16e80840-6ab1-5742-a371-0b65386c63e2'::uuid, 'Le vote en France est secret et égal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une personne, une voix, dans un isoloir : ce sont deux garanties distinctes.', 2),
    ('75d151ec-c1b1-5eef-947b-d7dbd3b9f922'::uuid, '16e80840-6ab1-5742-a371-0b65386c63e2'::uuid, 'Le droit du sol permet de devenir français…', 'mcq', '["Par la naissance et la résidence en France","Par le mariage uniquement","Par les parents uniquement","Par examen"]'::jsonb, 0, 'Le droit du sang, lui, passe par la nationalité des parents.', 3),
    ('8fc54a09-3f75-5568-b4b9-2d521e764092'::uuid, '16e80840-6ab1-5742-a371-0b65386c63e2'::uuid, 'Un citoyen européen non français peut voter en France…', 'mcq', '["Aux élections municipales et européennes","À toutes les élections","À aucune élection","À l’élection présidentielle"]'::jsonb, 0, 'C’est une conséquence de la citoyenneté européenne.', 4),
