    ('19639680-d141-578d-b831-b997fcb7132f'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Que garantit le RGPD ?', 'mcq', '["Des droits sur ses données personnelles","La gratuité d’internet","La liberté de la presse","Le droit d’auteur"]'::jsonb, 0, 'Information, accès, rectification, effacement, opposition.', 1),
    ('423f6551-909e-5b7a-823f-ecebe368296c'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Quelle autorité veille aux données personnelles en France ?', 'mcq', '["La CNIL","L’ARCOM","Le CSA","L’INSEE"]'::jsonb, 0, 'Commission nationale de l’informatique et des libertés.', 2),
    ('e4db3444-75e9-5657-9e4c-24795e6f122d'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Une information partagée par beaucoup de comptes est forcément vraie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La viralité mesure l’émotion suscitée, pas la véracité.', 3),
    ('d21aabbc-663a-55c7-a8de-10acfac0f05c'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Qu’est-ce qu’une bulle de filtre ?', 'mcq', '["Un environnement d’infos qui confirme nos opinions","Un antivirus","Un filtre photo","Un mode de paiement"]'::jsonb, 0, 'Les algorithmes personnalisent le flux et enferment.', 4),
    ('ca261ec0-30f7-522f-a1bf-26b560c063cd'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Publier la photo d’un camarade sans son accord…', 'mcq', '["Porte atteinte à son droit à l’image","Est autorisé si elle est drôle","Est autorisé entre amis","Est autorisé après 24 h"]'::jsonb, 0, 'Le droit à l’image découle du droit au respect de la vie privée.', 5),
    ('2a97688f-322e-535e-addc-70ce8af88663'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'La recherche d’image inversée sert à vérifier l’origine d’une photo.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle révèle souvent qu’une image ancienne est réutilisée hors contexte.', 6),
    ('dc60f8ce-0de2-51c7-b52b-34bd4658bd0a'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Le premier réflexe face à une information choquante est…', 'mcq', '["De chercher sa source et sa date","De la partager vite","De la commenter","De la croire"]'::jsonb, 0, 'L’émotion forte est justement le levier des fausses informations.', 7),
    ('99a8fd7f-999a-5d23-a403-4323cd2792f9'::uuid, 'c707ce60-5489-54d5-a45e-cf62f782a154'::uuid, 'Le droit à l’oubli permet de demander l’effacement de données.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il est prévu par le RGPD, sous conditions.', 8),
    ('d7e61712-001f-5538-97a3-f99aa7d65cf1'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'À quoi sert principalement l’échauffement ?', 'mcq', '["À préparer le corps et réduire le risque de blessure","À fatiguer avant l’effort","À perdre du poids","À gagner des points"]'::jsonb, 0, 'Il élève la température musculaire et prépare cœur et articulations.', 1),
    ('6b5436d7-37c1-5403-af3e-11dca552498a'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Combien de temps dure un échauffement complet ?', 'mcq', '["10 à 15 minutes","1 minute","45 minutes","2 heures"]'::jsonb, 0, 'Assez long pour élever la température, assez court pour ne pas fatiguer.', 2),
    ('22c4d362-8ccd-50f2-af77-6247ae48046f'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Pendant l’effort, la fréquence cardiaque augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cœur envoie plus de sang, donc plus d’oxygène, vers les muscles.', 3),
    ('63c8cf68-7c0c-53c6-b961-84f745ad488c'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Pourquoi transpire-t-on à l’effort ?', 'mcq', '["Pour évacuer la chaleur produite","Pour éliminer les graisses","Pour respirer mieux","Pour muscler la peau"]'::jsonb, 0, 'La transpiration est le système de refroidissement du corps.', 4),
    ('e18fd301-2750-5cbb-943c-be11719ca6d7'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Un sportif entraîné récupère plus vite qu’un débutant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La vitesse de retour au calme est un bon indicateur de condition physique.', 5),
    ('b22bbb21-def7-502e-b5fc-b28dfb94dbcf'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Que faire en cas de douleur vive pendant un exercice ?', 'mcq', '["S’arrêter et prévenir l’enseignant","Continuer pour finir","Courir plus vite","Boire beaucoup d’un coup"]'::jsonb, 0, 'La douleur vive est un signal d’alerte, pas un obstacle à franchir.', 6),
    ('abfab8d4-91f5-5480-be37-83600aa72b21'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'Après l’effort, il faut…', 'mcq', '["Ralentir progressivement et boire","S’asseoir immédiatement","Manger un repas complet","Prendre une douche froide"]'::jsonb, 0, 'Le retour au calme progressif aide la récupération.', 7),
    ('a8c903aa-bb1f-5b59-9c5b-1d783fe01112'::uuid, 'e14c06fd-f48b-520c-9ab0-d36f16089d66'::uuid, 'L’échauffement commence par le spécifique puis va vers le général.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : du général (course lente) vers le spécifique (gestes de l’activité).', 8),
    ('d6c73d7b-f980-55bc-b1a8-3adccd22205e'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Quelles sont les trois missions de l’attaque ?', 'mcq', '["Conserver, progresser, marquer","Courir, sauter, lancer","Défendre, gêner, récupérer","Passer, tirer, sortir"]'::jsonb, 0, 'Elles structurent toutes les activités collectives.', 1),
    ('36e3bf17-9899-5cee-8762-ae72bab86119'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Au volley-ball, combien de touches de balle par équipe au maximum ?', 'mcq', '["3","2","4","5"]'::jsonb, 0, 'Réception, passe, attaque : trois touches avant de renvoyer.', 2),
    ('2b2e8e91-cd71-5a6b-9fc3-86e5edb4d14f'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Se démarquer, c’est se placer pour pouvoir recevoir la balle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le joueur sans ballon crée les solutions de passe.', 3),
    ('120b0c88-ac52-5e86-a731-37c0c2f30bbd'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Au handball, combien de pas maximum sans dribbler ?', 'mcq', '["3","2","5","Aucun"]'::jsonb, 0, 'Trois pas, et trois secondes balle en main.', 4),
    ('9a700ae4-059c-517e-97d9-f58d148bc269'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Au basket, la reprise de dribble est autorisée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Reprendre son dribble après l’avoir arrêté est une faute.', 5),
    ('56b6dfee-b0e0-5526-b8d8-59946f6cb7a0'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Que fait une équipe qui perd le ballon ?', 'mcq', '["Elle passe immédiatement en défense","Elle sort du terrain","Elle demande un temps mort","Elle attend l’arbitre"]'::jsonb, 0, 'Le changement de statut est immédiat : c’est le rapport de force qui bascule.', 6),
    ('3c33c2c0-179d-5caf-908f-e2bb52858d90'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'Le fair-play consiste notamment à…', 'mcq', '["Accepter la décision de l’arbitre","Gagner à tout prix","Feindre une faute","Ignorer l’adversaire"]'::jsonb, 0, 'Sans acceptation des décisions, il n’y a plus de jeu possible.', 7),
    ('471fb4f1-58b5-5b1e-8c08-6b794a797aae'::uuid, '623de60e-f25c-5a0c-987a-85f644fc037d'::uuid, 'En défense, on cherche à protéger sa cible et récupérer la balle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont les deux missions défensives fondamentales.', 8),
    ('a8901c59-2b32-5b66-a503-5cd980214ca4'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Avant de grimper en escalade, on vérifie…', 'mcq', '["Le baudrier et le nœud, mutuellement","La météo","Sa vitesse","La hauteur du mur"]'::jsonb, 0, 'La vérification croisée est la règle de sécurité de base.', 1),
    ('535b658a-32f7-5169-b34f-3318eb9eb704'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'On peut plonger dans un bassin dont on ignore la profondeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’une des principales causes d’accidents graves.', 2),
    ('0d671ee5-5736-51a5-88a5-4ea08d017ab4'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Qu’est-ce que la parade en gymnastique ?', 'mcq', '["Accompagner le camarade pour éviter une chute dangereuse","Un enchaînement de figures","Une note de jury","Un échauffement"]'::jsonb, 0, 'C’est un rôle actif, qui s’apprend.', 3),
    ('316ea640-ecbc-54ec-8de6-ba8e1885d0ca'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Quand faut-il boire lors d’une séance de sport ?', 'mcq', '["Avant, pendant et après","Seulement après","Seulement si on a soif","Jamais pendant l’effort"]'::jsonb, 0, 'La soif apparaît quand la déshydratation a déjà commencé.', 4),
    ('eec8ff24-bf07-5626-b572-f8ed54857240'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Les bijoux doivent être retirés avant la pratique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Bagues, colliers et montres provoquent coupures et accrochages.', 5),
    ('9f54b8a1-b46e-5ea8-b1da-1ddfacdbebff'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Par forte chaleur, il faut…', 'mcq', '["Réduire l’intensité et chercher l’ombre","Augmenter l’effort","Éviter de boire","Se couvrir davantage"]'::jsonb, 0, 'La chaleur ajoute une charge au système cardiovasculaire.', 6),
    ('65346eed-23a5-53a8-bf00-a074c3677363'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Qu’est-ce que le test d’aisance aquatique ?', 'mcq', '["Une évaluation qui conditionne l’accès à certaines activités nautiques","Un chronomètre de natation","Un diplôme de sauveteur","Une épreuve du brevet"]'::jsonb, 0, 'Il atteste qu’un élève sait se débrouiller dans l’eau.', 7),
    ('80ad8df5-9163-5f96-b123-6482c6272870'::uuid, 'a9a8eacf-d6d4-5c33-b019-0097e41c8026'::uuid, 'Écouter les consignes avant un atelier fait partie de la sécurité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne s’engage jamais sans savoir ce qu’on va faire.', 8),
    ('cf906abd-bd9f-587d-aa86-5adae6b10a4a'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Comment estime-t-on simplement la fréquence cardiaque maximale ?', 'mcq', '["220 moins l’âge","180 moins l’âge","Le poids fois 3","La taille moins 100"]'::jsonb, 0, 'C’est une estimation rapide, utile pour calibrer une séance.', 1),
    ('8bf050b0-4e91-5eb9-ab3a-b85401d1b6b6'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Que signifie VMA ?', 'mcq', '["Vitesse maximale aérobie","Volume musculaire actif","Variation moyenne d’amplitude","Vitesse moyenne d’accélération"]'::jsonb, 0, 'C’est la vitesse à laquelle la consommation d’oxygène est maximale.', 2),
    ('c01225dd-edeb-56ac-89e6-2510ba89cd6a'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Un sprint de 8 secondes sollicite surtout la filière aérobie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sur un effort aussi court et intense, c’est l’anaérobie alactique.', 3),
    ('9cecb362-33aa-5362-998d-74ccce0407d6'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Dans quelle zone travaille-t-on l’endurance ?', 'mcq', '["60 à 80 % de la FC max","30 à 40 % de la FC max","95 à 100 % de la FC max","Peu importe"]'::jsonb, 0, 'C’est la zone où l’on peut encore parler en courant.', 4),
    ('112cf807-9920-5efe-98a9-269c9b35bdd0'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'L’entraînement régulier fait baisser la fréquence cardiaque de repos.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cœur, plus efficace, envoie plus de sang à chaque battement.', 5),
    ('0a63139e-312f-5b4a-a64b-542967fd65f3'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Quel test permet de mesurer sa VMA ?', 'mcq', '["Le test de Luc Léger","Le test de Cooper de force","Le test de souplesse","Le test d’équilibre"]'::jsonb, 0, 'Un test progressif par paliers, comme le VAMEVAL.', 6),
    ('e53eb7d5-6229-5207-b57a-eefce04fffe4'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'La filière anaérobie lactique concerne des efforts de…', 'mcq', '["10 secondes à 2 minutes","0 à 5 secondes","30 minutes et plus","2 heures"]'::jsonb, 0, 'Typiquement un 400 m, avec accumulation de lactate.', 7),
    ('c07309e3-be35-588e-ab9e-1b9570dc78f9'::uuid, '14019637-3c5b-53cb-9a28-1b6adeb6a3b1'::uuid, 'Il faut au moins deux à trois séances par semaine pour progresser durablement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La régularité prime sur l’intensité ponctuelle.', 8),
    ('49a4ac51-b6f2-5bb1-b48f-4cd0763cfe6f'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Que fait un observateur en EPS ?', 'mcq', '["Il relève des données concrètes sur le jeu","Il encourage seulement","Il arbitre","Il note les élèves"]'::jsonb, 0, 'Les relevés transforment une impression en fait mesurable.', 1),
    ('84300312-30d5-5f7f-b987-2d95e881e63a'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Un bon conseil de coach est…', 'mcq', '["Court, précis et positif","Long et détaillé","Critique et sévère","Donné après le match"]'::jsonb, 0, 'En pleine action, seul un message court est utilisable.', 2),
    ('71ec9c4f-f846-54cb-8335-d0463a271320'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Arbitrer aide à mieux comprendre le jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On découvre les règles de l’intérieur, donc les intentions du jeu.', 3),
    ('69fb9ffc-1692-56b5-9034-b498695899d9'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Qu’évalue un juge en gymnastique ?', 'mcq', '["La difficulté, l’exécution et la composition","La vitesse seule","Le nombre de points marqués","La taille de l’élève"]'::jsonb, 0, 'Les critères sont annoncés avant la prestation.', 4),
    ('398bfddb-d0b8-578c-b365-736b675f1dcd'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'L’arbitre doit surtout être…', 'mcq', '["Impartial et constant","Sévère","Silencieux","Du côté de la meilleure équipe"]'::jsonb, 0, 'La constance rend ses décisions prévisibles, donc acceptables.', 5),
    ('cabd3575-818d-5951-b298-ad595d25b8aa'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Un observateur peut relever le nombre de passes réussies.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un indicateur simple et parlant du jeu collectif.', 6),
    ('f55b9a81-0b30-5faa-9158-59b31c2bb5ce'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Contester systématiquement l’arbitre…', 'mcq', '["Désorganise le jeu et fait perdre du temps","Améliore l’arbitrage","Est un droit du joueur","Est recommandé"]'::jsonb, 0, 'Le jeu suppose une autorité acceptée.', 7),
    ('a7b3cd3c-8f90-54db-a70d-4a64470f1fbf'::uuid, '3762faab-9fb3-5e44-a9a7-83b3908cc22d'::uuid, 'Tenir un rôle social fait partie de l’évaluation en EPS.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les programmes intègrent explicitement ces rôles.', 8),
    ('87e11ea5-4ae9-5d4a-85dc-9f7a2e16ab67'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'La course d’orientation relève de quel champ d’apprentissage ?', 'mcq', '["Adapter ses déplacements à un milieu incertain","Produire une performance mesurée","Réaliser une prestation artistique","Conduire un affrontement"]'::jsonb, 0, 'Le milieu change et n’est pas maîtrisé : c’est le champ 2.', 1),
    ('aa55bba2-a9c6-53a3-ac68-cfec099587ec'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Le badminton relève du champ de l’opposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un adversaire cherche exactement l’inverse de ce qu’on veut.', 2),
    ('5afd3f99-4cc4-511c-9943-d027c4fc2891'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Quel champ regroupe danse, gymnastique et acrosport ?', 'mcq', '["La prestation artistique devant un public","La performance mesurée","Le milieu incertain","L’opposition"]'::jsonb, 0, 'On y est jugé sur une composition présentée.', 3),
    ('e8b1e8f4-8ebf-5876-aa3a-4031b777fa24'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Combien de champs d’apprentissage structurent l’EPS ?', 'mcq', '["4","3","5","6"]'::jsonb, 0, 'Performance, milieu incertain, prestation artistique, opposition.', 4),
    ('bd6fabc3-1bbf-5f91-8bcd-0779d253611d'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Le 800 m relève de la performance mesurée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il s’agit de produire sa meilleure performance en gérant son allure.', 5),
    ('04d5eac9-e162-5a4f-ba7e-1c3a95ea0e7b'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Dans le champ « milieu incertain », la difficulté vient…', 'mcq', '["De l’environnement qui change","Du chronomètre","Du jury","De l’adversaire"]'::jsonb, 0, 'Relief, vent, courant, itinéraire : le milieu impose ses conditions.', 6),
    ('59ffcba6-9284-5b98-942e-74b4cfdb0ee9'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Le judo appartient au champ de la prestation artistique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un sport d’opposition : un adversaire s’oppose directement.', 7),
    ('3d47e2b8-56d0-5626-a851-1927f60fb292'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Une même qualité physique peut se travailler dans plusieurs champs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’endurance sert en course comme en sport collectif ; le problème posé diffère.', 8),
